-    --menuitem-icon: var(--webextension-toolbar-image-dark, inherit);
+  @media not (-moz-native-theme) {
+    @media (prefers-color-scheme: light) {
+      --menuitem-icon: var(--webextension-toolbar-image-dark, inherit);
+    }
   }
 }

@@ -33,8 +37,10 @@
