+    @media (prefers-color-scheme: light) {
+      content: var(--webextension-toolbar-image-dark, inherit);
+    }
   }
 }

@@ -59,8 +65,10 @@
     list-style-image: var(--webextension-menupanel-image-light, inherit);
   }

-  :root[lwtheme]:not([lwt-popup-brighttext]) & {
